  1 import React, { useEffect, useRef } from "react";
  2 import { X, type LucideIcon } from "lucide-react";
  3 import { Button } from "@/components/ui/button";
  4 import { cn } from "@/lib/utils";
  5 
  6 interface PanelStripTab {
  7   id: string;
  8   label: string;
  9   icon: LucideIcon;
 10 }
 11 
 12 interface Props {
 13   tabs: PanelStripTab[];
 14   activeId: string | null;
 15   idPrefix: string;
 16   hidden: boolean;
 17   label: string;
 18   closeLabel: string;
 19   onActivate: (id: string) => void;
 20   onClose: (id: string) => void;
 21   /** The focused last tab disappeared; its host owns the surviving opener. */
 22   onRestoreFocus?: () => void;
 23 }
 24 
 25 /** Only the tabs scroll; dock actions remain visible beside this strip. */
 26 export function PanelTabStrip({
 27   tabs,
 28   activeId,
 29   idPrefix,
 30   hidden,
 31   label,
 32   closeLabel,
 33   onActivate,
 34   onClose,
 35   onRestoreFocus,
 36 }: Props) {
 37   const tabButtons = useRef(new Map<string, HTMLButtonElement>());
 38 
 39   useEffect(() => {
 40     if (hidden || !activeId) return;
 41     tabButtons.current.get(activeId)?.scrollIntoView?.({ block: "nearest", inline: "nearest" });
 42   }, [activeId, hidden, tabs.length]);
 43 
 44   const close = (id: string, retainFocus: boolean) => {
 45     const index = tabs.findIndex((tab) => tab.id === id);
 46     const remaining = tabs.filter((tab) => tab.id !== id);
 47     const nextId = id === activeId ? remaining[Math.max(0, index - 1)]?.id : activeId;
 48     onClose(id);
 49     if (!retainFocus) return;
 50     if (nextId) tabButtons.current.get(nextId)?.focus();
 51     else if (remaining.length === 0) onRestoreFocus?.();
 52   };
 53 
 54   return (
 55     <div
 56       role="tablist"
 57       aria-label={label}
 58       aria-orientation="horizontal"
 59       className="flex min-w-0 flex-1 items-center gap-1 overflow-x-auto px-1 py-1 [scrollbar-width:thin]"
 60     >
 61       {tabs.map((tab, index) => {
 62         const active = tab.id === activeId;
 63         const Icon = tab.icon;
 64         return (
 65           <div
 66             key={tab.id}
 67             role="presentation"
 68             className={cn(
 69               "group flex h-8 min-w-0 shrink-0 items-center rounded-lg border transition-colors",
 70               active
 71                 ? "border-border/80 bg-background text-foreground shadow-sm"
 72                 : "border-transparent text-muted-foreground hover:bg-accent/60 hover:text-foreground",
 73             )}
 74           >
 75             <Button
 76               ref={(node) => {
 77                 if (node) tabButtons.current.set(tab.id, node);
 78                 else tabButtons.current.delete(tab.id);
 79               }}
 80               type="button"
 81               role="tab"
 82               id={`${idPrefix}-tab-${tab.id}`}
 83               aria-controls={`${idPrefix}-body-${tab.id}`}
 84               aria-selected={active}
 85               tabIndex={active ? 0 : -1}
 86               title={tab.label}
 87               variant="ghost"
 88               className="h-full min-w-0 max-w-44 justify-start gap-1.5 rounded-l-lg rounded-r-none py-0 pl-2.5 pr-1.5 text-xs hover:bg-transparent focus-visible:ring-inset"
 89               onClick={() => onActivate(tab.id)}
 90               onKeyDown={(event) => {
 91                 if (event.altKey || event.ctrlKey || event.metaKey) return;
 92                 let nextIndex: number;
 93                 switch (event.key) {
 94                   case "ArrowLeft":
 95                     nextIndex = (index - 1 + tabs.length) % tabs.length;
 96                     break;
 97                   case "ArrowRight":
 98                     nextIndex = (index + 1) % tabs.length;
 99                     break;
100                   case "Home":
101                     nextIndex = 0;
102                     break;
103                   case "End":
104                     nextIndex = tabs.length - 1;
105                     break;
106                   case "Delete":
107                     event.preventDefault();
108                     close(tab.id, event.currentTarget === document.activeElement);
109                     return;
110                   default:
111                     return;
112                 }
113                 event.preventDefault();
114                 const nextId = tabs[nextIndex].id;
115                 onActivate(nextId);
116                 tabButtons.current.get(nextId)?.focus();
117               }}
118             >
119               <Icon className={cn("size-3.5", active && "text-primary")} />
120               <span className="truncate">{tab.label}</span>
121             </Button>
122             <Button
123               type="button"
124               aria-label={`${closeLabel}: ${tab.label}`}
125               title={`${closeLabel}: ${tab.label}`}
126               tabIndex={active ? 0 : -1}
127               variant="ghost"
128               size="icon"
129               className={cn(
130                 "mr-1 size-6 shrink-0 rounded-md text-muted-foreground hover:bg-muted hover:text-foreground group-focus-within:opacity-100 group-hover:opacity-100 focus-visible:opacity-100 focus-visible:ring-inset",
131                 active ? "opacity-100" : "opacity-40",
132               )}
133               onClick={(event) => close(tab.id, event.currentTarget === document.activeElement)}
134             >
135               <X className="size-3" />
136             </Button>
137           </div>
138         );
139       })}
140     </div>
141   );
142 }
